def deprecated(message):
    """ Decorator for deprecating functions and methods.

    :param message: The deprecation message to display.
    """
    def deprecated_decorator(func):
        func.__deprecated__ = message
        @wraps(func)
        def deprecated_func(*args, **kwargs):
            warnings.warn(message, category=DeprecationWarning)
            return func(*args, **kwargs)
        return deprecated_func
    return deprecated_decorator

def cached(cache, key=None, lock=None):
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            if key:
                key = key(*args)
            try:
                return cache[key]
            except KeyError:
                result = func(*args, **kwargs)
                if key:
                    cache[key] = result
                return result
            finally:
                if lock:
                    lock.release()
        return wrapper
    return decorator

def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    def decorator(func):
        cache = utils.LRUCache(maxsize, getsizeof=None, timer=timer, typed=typed)
        @wraps(func)
        def wrapper(*args, **kwargs):
            key = args + tuple(sorted(kwargs.items())) if not typed else args
            current_time = timer()
            cache_entry = cache.get(key, None)
            if cache_entry is not None and cache_entry.created_at + ttl > current_time:
                return cache_entry.value
            else:
                value = func(*args, **kwargs)
                cache.put_with_ttl(key, value, current_time)
                return value
        return wrapper
    return decorator

def lru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm.

    @param maxsize The maximum number of results to store in the cache
    @param typed Whether to distinguish objects based on their type
    @return The cached function

    @raise TypeError If the function is not able to cache the result

    The decorated function will be memoized based on the input parameters
    passed to it, up to the specified `maxsize`. If the `typed` parameter
    is set to `True`, the function will only store results that are of the
    same type. If the cache is full, the LRU algorithm will be used to
    determine which result to remove from the cache.

def lfu_cache(maxsize=128, typed=False):
    class LFUCache:
        def __init__(self):
            self.maxsize = maxsize
            self.typed = typed
            self.cache = {}

        def formula(self, key):
            d = self.cache[key]['data']
            x = [1/self.cache[key][a] for a in self.cache[key]]
            return sum(x)

        def get(self, key):
            if key in self.cache:
                self.cache[key]['data'] += 1
                return self.cache[key]['data']
            return -1

        def set(self, key, data):
            if key in self.cache and self.cache[key]['data'] == -1:
                self.cache[key]['data'] = data
                return self.cache[key]['data']
            if len(self.cache) >= self.maxsize:
                min_ = min(self.cache, key=lambda x: self.cache[x]['data'])
                del self.cache[min_]
            self.cache[key] = {'data': data}
            return self.cache[key]['data']

        def __call__(self, func):
            def wrapper(*args, **kwargs):
                if len(args) == 0:
                    kwargs['typed'] = -1
                if len(args) == 1:
                    kwargs['typed'] = True if isinstance(args[0], str) else False
                key = args[0] if len(args) == 1 else kwargs
                if not self.typed:
                    key = str(key)
                if self.get(key) == -1 or self.typed == True:
                    res = func(*args, **kwargs)
                    self.set(key, (res, False))
                    return None
                else:
                    return None

            return wrapper

    return LFUCache()

