def difference(d1, d2, level=-1):
    # Check if level is valid
    if level < -1:
        raise ValueError("level must be either -1 or a positive integer")
    # Check types
    if not isinstance(d1, dict) or not isinstance(d2, dict):
        raise TypeError("d1 and d2 must be dictionaries")
    # Initialize difference dictionary
    diff = {}
    # Add items from d1 that are not in d2
    for key, value in d1.items():
        if key not in d2:
            diff[key] = value
    # Check for recursive difference
    if level >= 1:
        for key, value in d1.items():
            if key in d2 and isinstance(value, dict) and value != d2[key]:
                diff[key] = recursive_difference(value, d2[key], level=level-1)
    return diff

