def validate(self, inventory, extract_spec_version=False):
    """Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine the specification version. In the case that there is no type value or it isn't valid, then other tests will be based on the version given in self.spec_version.

    Arguments:
        inventory (Inventory): The inventory to validate
        extract_spec_version (bool, optional): Whether to extract the specification version from the inventory's type value. Defaults to False.

    Raises:
        ValueError: If the inventory is not valid
    """
    # Check if the inventory has a type value and that it is valid
    if extract_spec_version:
        if not inventory.type:
            raise ValueError("Inventory has no type value")
        try:
            self.spec_version = float(inventory.type)
        except ValueError:
            raise ValueError("Inventory has invalid type value")
    # Check if the version matches the inventory's type value if it exists
    if self.spec_version != inventory.type:
        raise ValueError("Inventory version does not match")
    # Check if the inventory has a name
    if not inventory.name:
        raise ValueError("Inventory has no name")
    # Check if the inventory has a vendor
    if not inventory.vendor:
        raise ValueError("Inventory has no vendor")
    # Check if the inventory has a model
    if not inventory.model:
        raise ValueError("Inventory has no model")
    # Check if the inventory has a revision
    if not inventory.revision:
        raise ValueError("Inventory has no revision")
    # Check if the inventory has at least one component
    if len(inventory.components) == 0:
        raise ValueError("Inventory has no components")

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    # Create a set of all digests in the manifest
    digests_all = {x.split(' ')[0] for x in manifest_files if x.startswith('DIGESTS : ')}
    # Check if all needed digests are present in the manifest
    digests_needed = set(digests_used) | set(self.get_missing_digests())
    if digests_needed - digests_all:
        raise ValueError('The following digests are needed but not present in the manifest: {}'.format(digests_needed - digests_all))
    # Check if all used digests are present in the manifest
    digests_used = digests_used - self.get_missing_digests()
    if digests_used - digests_all:
        raise ValueError('The following digests are used but not present in the manifest: {}'.format(digests_used - digests_all))
    return digests_needed

def validate_as_prior_version(self, prior):
        """Check that prior is a valid prior version of the current inventory object.

        The input variable prior is also expected to be an InventoryValidator object
        and both self and prior inventories are assumed to have been checked for
        internal consistency.
        """
        # Check if prior and self have the same class
        if self.__class__ != prior.__class__:
            raise TypeError("Input prior is not the same class as self")

        # Check if prior and self have the same audit trail
        if self.audit_trail != prior.audit_trail:
            raise ValueError("Input prior does not have the same audit trail as self")

        # Check if prior and self have the same parent
        if self.parent != prior.parent:
            raise ValueError("Input prior does not have the same parent as self")

        # Check if prior and self have the same child elements
        if self.children != prior.children:
            raise ValueError("Input prior does not have the same child elements as self")

        # Check if prior and self have the same attributes
        if self.attributes != prior.attributes:
            raise ValueError("Input prior does not have the same attributes as self")

        # Check if prior and self have the same text content
        if self.text_content != prior.text_content:
            raise ValueError("Input prior does not have the same text content as self")

        # Check if prior and self have the same scope
        if self.scope != prior.scope:
            raise ValueError("Input prior does not have the same scope as self")

        # Check if prior and self have the same inverted index
        if self.inverted_index != prior.inverted_index:
            raise ValueError("Input prior does not have the same inverted index as self")

        # Check if prior and self have the same relations
        # Recursively check all children and attributes
        if len(self.relations) != len(prior.relations):
            raise ValueError("Input prior does not have the same number of relations as self")
        else:
            for rel in self.relations:
                for child in rel.children:
                    if child not in prior.relations:
                        raise ValueError("Input prior does not have the same children in one of the relations")
                    if child. relativeship_type != rel.type:
                        raise ValueError("Input prior does not have the same children in one of the relations")
                    if rel.conditions != rel.conditions:
                        raise ValueError("Input prior does not have the same conditions in one of the relations")

        # Everything has been checked, the input prior is a valid prior version
        return True

