def size_to_bytes(size: str) -> int:
    units = {"K": 1000, "M": 1000000, "G": 1000000000}
    if not size:
        return 0
    if size.isdigit():
        return int(size)
    unit = size[-1]
    if unit in units:
        return int(size[:-1]) * units[unit]
    return 0

