def parse_frequency(frequency):
    """
    Given a frequency string with a number and a unit of time, return a corresponding datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    """

    if not frequency:
        return None
    if frequency == "always":
        return None

    freq_parts = frequency.split()
    num = int(freq_parts[0])
    unit = freq_parts[1].lower()

    if unit == "hour":
        return datetime.timedelta(hours=num)
    elif unit == "day":
        return datetime.timedelta(days=num)
    elif unit == "week":
        return datetime.timedelta(weeks=num)
    elif unit == "month":
        return datetime.timedelta(days=num * 30)
    elif unit == "year":
        return datetime.timedelta(days=num * 365)

    raise ValueError(f"Invalid frequency string: '{frequency}'")

