    if other is None:
        return self.scale
    elif isinstance(other, (int, float)):
        if self.scale == 0 or self.scale is None:
            raise LenaValueError("Unknown or zero scale, cannot rescale.")

        self.scale = other
        for field, fieldvalues in self.fields.items():
            if field.endswith("_error"):
                self.fields[field] = (fieldvalues[0] / self.scale) * other
    else:
        raise TypeError("Expected None or numeric value, got {0}".format(type(other).__name__))

def hist_to_graph(hist, make_value=None, get_coordinate="left", field_names=("x", "y"), scale=None):
    if not isinstance(hist, Histogram):
        raise TypeError("hist must be a Histogram object")
    if not callable(make_value) and make_value is not None:
        raise TypeError("make_value must be either None or callable")
    if get_coordinate not in ("left", "middle", "right"):
        raise ValueError("get_coordinate must be either 'left', 'middle' or 'right'")
    if scale not in (None, True):
        raise ValueError("scale must be either None or True")
    if not isinstance(field_names, (list, tuple)):
        raise TypeError("field_names must be a list or tuple")
    if len(field_names) != hist.dimension:
        raise ValueError(f"length of field_names must be {hist.dimension}")

    if scale is None:
        scale = hist.scale
    graph = Graph()

    i = 0
    while (i + 1) * hist.bin_width < hist.size[0]:
        x = i * hist.bin_width
        if get_coordinate == "left":
            x += hist.bin_width / 2
        elif get_coordinate == "right":
            x -= hist.bin_width / 2
        bins = hist.get_bins(x, i * hist.bin_width)
        if not bins:
            raise ValueError("hist contains only empty bins")
        bin_coord = bins[0][get_coordinate]
        value = None
        if make_value is not None:
            value = make_value(bins[0])
        for field_name, bin_value in zip(field_names, value):
            graph.add_point(bin_coord, bin_value, field_name)
        i += 1
    return graph

def _verify(iface, candidate, tentative=False, vtype=None):
    provided_by_candidate = iface.providedBy(candidate)
    if not provided_by_candidate and not tentative:
        raise zope.interface.Invalid(
            "Candidate does not declare that it provides the interface"
        )

    necessary_attributes = iface.getAttributes()
    for attribute in necessary_attributes:
        if attribute.name not in candidate:
            raise zope.interface.Invalid(
                "Attribute %s is missing from %s" % (attribute.name, candidate)
            )

    necessary_methods = iface.getMethods()
    for method in necessary_methods:
        if method.name not in candidate:
            raise zope.interface.Invalid(
                "Method %s is missing from %s" % (method.name, candidate)
            )
        else:
            candidate_method = getattr(candidate, method.name)
            if not all([p.annotation.type in candidate_method.parameters for p in method.parameters]):
                raise zope.interface.Invalid(
                    "Parameter types do not match for method %s on %s" % (method.name, candidate)
                )
            if method.result.type != candidate_method.return_type:
                raise zope.interface.Invalid(
                    "Return type does not match for method %s on %s" % (method.name, candidate)
                )

    return True

def verifyClass(iface, candidate, tentative=False):
        """
        Verify that the *candidate* might correctly provide *iface*.
        """
        if not isinstance(iface, ElementInterface):
            raise TypeError("iface must be an ElementInterface, not " + str(type(iface)))
        if not isinstance(candidate, (Item, Document)):
            raise TypeError("candidate must be an Item or Document, not " + str(type(candidate)))
        if not isinstance(tentative, bool):
            raise TypeError("tentative must be a boolean, not " + str(type(tentative)))

        # Check if the candidate element provided all required attributes
        for attrib_name in iface.REQUIRED_ATTRIBS:
            if attrib_name not in candidate.attribs:
                if tentative:
                    return False
                else:
                    raise MissingAttributeError("Required attribute " + attrib_name + " is missing from element " + str(candidate))

        # Check if the candidate element provided all required relations
        for rel in iface.REQUIRED_RELS:
            if rel.opposite not in candidate.attribs:
                if tentative:
                    return False
                else:
                    raise MissingRelationError("Required relation " + rel.name + " is missing from element " + str(candidate))

        # Check if the candidate element provided all required features
        for feat in iface.REQUIRED_FEATURES:
            if not candidate.has_feature(feat):
                if tentative:
                    return False
                else:
                    raise MissingFeatureError("Required feature " + feat.name + " is missing from element " + str(candidate))

        return True

def pop(self, key, default=__marker):
    if key in self:
        value = self[key]
        del self[key]
        return value
    elif default is __marker:
        raise KeyError(key)
