        return default

def popitem(self):
    if len(self.items) == 0:
        raise KeyError("popitem(): dictionary is empty")

    min_freq = min(self.freq.values())
    for k, v in self.items.items():
        if self.freq[k] == min_freq:
            del self.freq[k]
            return k, v

    raise KeyError("popitem(): item was not found in the dictionary")

def popitem(self):
        if len(self) == 0:
            raise KeyError("popitem(): collection is empty")
        else:
            last_key = next(reversed(self))
            value = self[last_key]
            del self[last_key]
            return last_key, value

