    :param tzinfos: Additional time zone names / aliases which may be present in the string. This argument maps time zone names (and optionally offsets from those time zones) to time zones. This parameter can be a dictionary with timezone aliases mapping time zone names to time zones or a function taking two parameters (`tzname` and `tzoffset`) and returning a time zone. The timezones to which the names are mapped can be an integer offset from UTC in seconds or a `tzinfo` object.
    :param \\*\\*kwargs: Keyword arguments as passed to `_parse()`.
    :return: Returns a datetime.datetime object or, if the `fuzzy_with_tokens` option is True, a tuple, the first element being a datetime.datetime object, the second a tuple containing the fuzzy tokens.
    :raises ParserError: Raised for invalid or unknown string format, if the provided `tzinfo` is not in a valid format, or if an invalid date would be created.
    :raises TypeError: Raised for non-string or character stream input.
    :raises OverflowError: Raised if the parsed date exceeds the largest valid C integer on your system.
    """
    if not isinstance(timestr, str):
        raise TypeError("timestr parameter must be a string")
    if default is not None and not isinstance(default, datetime.datetime):
        raise TypeError("default parameter must be a datetime.datetime object")
    if ignoretz is not None and not isinstance(ignoretz, bool):
        raise TypeError("ignoretz parameter must be a boolean")
    if tzinfos is not None and not isinstance(tzinfos, dict):
        raise TypeError("tzinfos parameter must be a dictionary")
    if not isinstance(kwargs, dict):
        raise TypeError("kwargs parameter must be a dictionary")

    parser_kwargs = {}
    for key, value in kwargs.items():
        if key not in ["fuzzy_with_tokens", "target"]:
            parser_kwargs[key] = value

    parser = CParser(**parser_kwargs)
    tokens, time_tuple, tz_info = parser.parse(timestr, default=default, ignoretz=ignoretz, tzinfos=tzinfos)

    if not time_tuple:
        return None

    date = datetime.datetime(*time_tuple)

    if tz_info is not None and hasattr(date, "tzinfo"):
        date = self.combine(date, tz_info)

    if kwargs.get("target", datetime.datetime) is datetime.datetime:
        return date
    elif kwargs.get("target", datetime.date) is datetime.date:
        return date.date()
    elif kwargs.get("target", datetime.time) is datetime.time:
        return date.time()
    else:
        raise ValueError("unknown target type")

def fromutc(self, dt):
        """
        Given a timezone-aware datetime in a given timezone, calculates a
        timezone-aware datetime in a new timezone.

        Since this is the one time that we *know* we have an unambiguous
        datetime object, we take this opportunity to determine whether the
        datetime is ambiguous and in a "fold" state (e.g. if it's the first
        occurrence, chronologically, of the ambiguous datetime).

        :param dt:
            A timezone-aware :class:`datetime.datetime` object.
        """
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is not None:
                dt = dt.replace(tzinfo=dt.tzinfo)
        else:
            raise ValueError("fromutc requires a datetime instance "
                             "as input")

        if dt.tzinfo is None:
            raise ValueError("fromutc requires a timezone-aware "
                             "datetime instance as input")

        if isinstance(dt.tzinfo, timezone):
            return dt.tzinfo.convert(dt)
        else:
            return dt.astimezone(tz=self)

def default_tzinfo(dt, tzinfo):
    if dt.tzinfo is None:
        return tzinfo.fromutc(datetime.datetime.combine(dt.date(), dt.time()))
    else:
        return dt

def identify_request(request: RequestType):
    """Try to identify whether this is a Diaspora request.

    Try first public message. Then private message. The check if this is a legacy payload.
    """

    if isinstance(request, PublicMessage):
        return request
    elif isinstance(request, PrivateMessage):
