def retrieve_diaspora_host_meta(host):
    """
    Retrieve a remote Diaspora host-meta document.

    :arg host: Host to retrieve from
    :returns: ``XRD`` instance
    """
    try:
        http_response = urlopen("http://" + host + "/host-meta")
        xrd_data = http_response.read().decode("utf-8")
        return XRD(xrd_data)
    except HTTPError as e:
        if e.code == 401:
            raise DiasporaAuthorizationError("Unable to retrieve host-meta from " + host + " due to authorization error")
        elif e.code == 404:
            raise DiasporaHostMetaRetrievalError("Unable to retrieve host-meta from " + host + " (404 Not Found)")
        else:
            raise DiasporaHostMetaRetrievalError("Error retrieving host-meta from " + host + ": " + e.reason)
    except ValueError as e:
        if "Unknown encoding" in e.args[0]:
            raise DiasporaHostMetaRetrievalError("Unable to retrieve host-meta from " + host + " (unsupported encoding)")
        else:
            raise
    except URLError as e:
        raise DiasporaHostMetaRetrievalError("Error retrieving host-meta from " + host + ": " + e.reason)

def send_document(url, data, timeout=10, method="post", *args, **kwargs):
    """Helper method to send a document via POST.

    Additional ``*args`` and ``**kwargs`` will be passed on to ``requests.post``.

    :arg url: Full url to send to, including protocol
    :arg data: Dictionary (will be form-encoded), bytes, or file-like object to send in the body
    :arg timeout: Seconds to wait for response (defaults to 10)
    :arg method: Method to use, defaults to post
    :returns: Tuple of status code (int or None) and error (exception class instance or None)
    """

    try:
        request = requests.post(url, data=data, timeout=timeout, *args, **kwargs)
        return (request.status_code, None)
    except (ConnectTimeout, ConnectionError) as e:
        return (None, e)

