def validate_choices_args(self, args):
    for key, value in args.items():
        if key.endswith("_choices"):
            if value not in self.config.pop("choices", ""):
                raise ValueError(f"'{value}' is not one of the available choices for {key}")
    return args

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """

    # Validate minimum values
    for arg, value in args.items():
        if arg in self.minimum_values and value < self.minimum_values[arg]:
            raise ValueError(f"Minimum value for argument '{arg}' is {self.minimum_values[arg]}, got {value}.")

    # Validate maximum values
    for arg, value in args.items():
        if arg in self.maximum_values and value > self.maximum_values[arg]:
            raise ValueError(f"Maximum value for argument '{arg}' is {self.maximum_values[arg]}, got {value}.")

