def get_nested_custom_and_control_args(self, args):
    control_args = {}
    nested_args = {}
    custom_args = {}
    for arg in args:
        if arg.startswith("--"):
            control_args[arg[2:]] = True
        elif arg.startswith("-"):
            arg_split = arg[1:].split("=")
            key = arg_split[0]
            value = arg_split[1]
            if value.startswith("="):
                value = value[1:]
            if key.startswith("@"):
                custom_args[key] = value
            else:
                nested_args[key] = value
    return control_args, nested_args

