    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """
    if not vars_dict:
        vars_dict = {}
    if extra_vars:
        for extra_var in extra_vars:
            vars_dict[extra_var] = os.environ[extra_var]
    return vars_dict

def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """

    # Load the config, if a global one exists
    if self.config_file:
        self.config = self.load_config(parser_name)

    # Load the command-line parameters
    for param in self.params:
        cls = param.get("type")
        if cls is None:
            cls = str
        if param["name"] not in values_dict:
            continue
        try:
            values_dict[param["name"]] = cls(values_dict[param["name"]])
        except ValueError as e:
            raise ValueError(f"Error converting parameter '{param['name']}' to type '{cls.__name__}': {e}")

